css:
.status-container {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 20px;
}

.status {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background-color: #222533;
  color: #fbebe2;
  padding: 20px;
  width: 200px;
  height: 200px;
  border-radius: 26px;
  user-select: none;
  -moz-user-select: none;
  -webkit-user-select: none;
  transition: all 0.3s ease-in-out;
  border: transparent 1px solid;
}

.status span {
  font-size: 3.5rem;
  font-weight: 900;
  transition: all 0.3s ease-in-out;
}

.status p {
  font-size: 12px;
  transition: all 0.3s ease-in-out;
}

.status:hover {
  background-color: #1d1d1d;
  transform: scale(1.1);
  border: #5e63ff 1px solid;
}

.status:hover p {
  font-size: 15px;
  font-weight: 500;
  color: #b1cbf6;
}

.status:hover span {
  font-size: 4rem;
  color: #5e63ff;
}

.mac-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 15px;
}

.mac-header span {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mac-header .red {
  background-color: #ff5f57;
}

.mac-header .yellow {
  background-color: #ffbd2e;
}

.mac-header .green {
  background-color: #28c941;
}

@media (max-width: 768px) {
  .status-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
  }
}
